import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Surface
import androidx.navigation.NavType
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.navigation.navArgument
import com.example.ancapp.ui.detail.PatientDetailScreen
import com.example.ancapp.ui.newvisit.NewVisitScreen
import com.example.ancapp.ui.register.RegisterScreen

class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    setContent {
      MaterialTheme {
        Surface {
          val navController = rememberNavController()
          NavHost(navController = navController, startDestination = "register") {
            composable("register") {
              RegisterScreen(
                onPatientClick = { patientId -> navController.navigate("detail/$patientId") },
              )
            }
            composable(
              route = "detail/{patientId}",
              arguments = listOf(navArgument("patientId") { type = NavType.StringType }),
            ) { backStackEntry ->
              val patientId = backStackEntry.arguments?.getString("patientId").orEmpty()
              PatientDetailScreen(
                patientId = patientId,
                onBack = { navController.popBackStack() },
                onAddVisit = { navController.navigate("newVisit/$patientId") },
              )
            }
            composable(
              route = "newVisit/{patientId}",
              arguments = listOf(navArgument("patientId") { type = NavType.StringType }),
            ) { backStackEntry ->
              val patientId = backStackEntry.arguments?.getString("patientId").orEmpty()
              NewVisitScreen(
                patientId = patientId,
                onSaved = { navController.popBackStack() },
                onCancel = { navController.popBackStack() },
              )
            }
          }
        }
      }
    }
  }
}

