        it is CurrentSyncJobStatus.Failed ||
        it is CurrentSyncJobStatus.Cancelled
    }
    if (terminal !is CurrentSyncJobStatus.Succeeded) {
      val infos = androidx.work.WorkManager.getInstance(context.applicationContext)
        .getWorkInfosByTag("com.example.ancapp.sync.AncSyncWorker")
        .get()
      infos.forEach { info ->
        android.util.Log.e("AncDebug", "state=${info.state} output=${info.outputData.keyValueMap}")
      }
    }
    terminal is CurrentSyncJobStatus.Succeeded
  } catch (e: Exception) {
    android.util.Log.e("AncDebug", "sync threw", e)
    false
  }

/** Pushes local changes (e.g. a just-recorded visit) up to the server; best-effort. */
suspend fun pushLocalChanges(context: Context) {
  try {
    Sync.oneTimeSync<AncSyncWorker>(
      context.applicationContext,
      existingWorkPolicy = ExistingWorkPolicy.APPEND_OR_REPLACE,
    ).first {
      it is CurrentSyncJobStatus.Succeeded ||
        it is CurrentSyncJobStatus.Failed ||
        it is CurrentSyncJobStatus.Cancelled
    }
  } catch (e: Exception) {
    // best-effort: the visit is already safely persisted locally
  }
}

